import java.sql.Connection; import java.sql.DriverManager; import java.sql.Statement; public class DropConstraint { public static void main(String[] args) { String url = "jdbc:postgresql://localhost:5432/LabResourceDB"; String user = "postgres"; String password = "Nirbhay"; try (Connection conn = DriverManager.getConnection(url, user, password); Statement stmt = conn.createStatement()) { try { stmt.execute("ALTER TABLE bookings DROP CONSTRAINT IF EXISTS bookings_status_check;"); System.out.println("Dropped bookings_status_check successfully."); } catch (Exception e) { System.out.println("Error dropping constraint: " + e.getMessage()); } } catch (Exception e) { e.printStackTrace(); } } }